import{_ as e,c as o,o as r,af as t}from"./chunks/framework.r60quYNK.js";const p=JSON.parse('{"title":"南昌 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/NanChang.md","filePath":"2_articles/travel_record/NanChang.md"}'),c={name:"2_articles/travel_record/NanChang.md"};function d(l,a,n,i,h,_){return r(),o("div",null,a[0]||(a[0]=[t('<h1 id="南昌-2025" tabindex="-1">南昌 - 2025 <a class="header-anchor" href="#南昌-2025" aria-label="Permalink to &quot;南昌 - 2025&quot;">​</a></h1><h2 id="_6月7日-6月9日-☀️" tabindex="-1">6月7日 - 6月9日 ☀️ <a class="header-anchor" href="#_6月7日-6月9日-☀️" aria-label="Permalink to &quot;6月7日 - 6月9日 ☀️&quot;">​</a></h2><blockquote><p>我和黛黛同学本科毕业旅行的第一站！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>黛黛大学四年里就一直想看看我生活了四年的城市到底是什么样子，趁着毕业前我们都没事情，就决定把毕业旅行的第一站设在南昌</p><h3 id="_6月7日" tabindex="-1">6月7日 <a class="header-anchor" href="#_6月7日" aria-label="Permalink to &quot;6月7日&quot;">​</a></h3><p>原来黛黛定的是7号一大早的飞机，结果南昌暴雨导致航班取消，又赶紧重新买了下午的高铁，下午带着黛黛最喜欢的花和惊喜大疆Pocket3去南昌西站接她，开始了我们第一个旅行vlog的拍摄！晚上我们一起去吃了南昌特色的辣椒炒肉，给她留下了非常深的记忆哈哈哈。</p><h3 id="_6月8日" tabindex="-1">6月8日 <a class="header-anchor" href="#_6月8日" aria-label="Permalink to &quot;6月8日&quot;">​</a></h3><p>8号的一大早我们一起去学校拍了一组非常绝美的毕业照，中午带她去吃了我在南昌认可的第二美食<code>鸡杂面</code>和<code>冰醪糟</code>，明明是川菜，但后面我们去成都没有发现一家店......之后我们又一起走了我每天健身的NPC路线，下午去了八一广场、南昌美术馆、珠宝街、万寿宫，吃了<code>南昌拌粉</code>和<code>瓦罐汤</code>m，晚上又带她去了滕王阁，在她的乱走之下，发现了一条我从来没有发现的绝美取景点，在那里大拍特拍到很晚，然后又经历了我们的经典行为：<code>因为聊天太入迷导致错过站</code>。回到酒店两个吃货又想吃烧烤，结果在酒店附近找了家非常非常非常贵的重庆烧烤，还没吃完就下了暴雨，我们一起在雨中边喝酒边聊天，畅聊了我们的未来，最后实在太晚了，找老板借了把伞走了。</p><h3 id="_6月9日" tabindex="-1">6月9日 <a class="header-anchor" href="#_6月9日" aria-label="Permalink to &quot;6月9日&quot;">​</a></h3><p>因为前一天晚上吃完烧烤回酒店就一点多了，两个懒鬼一直睡到第二天下午一点，睡醒直奔我认可的南昌第一特色美食店<code>玉河人家</code>，结果惨遭厨师不在饭点不上班无功而返，被迫吃了我认为和麻辣烫没有任何区别的<code>南昌水煮</code>，因为起的太晚所以我们取消了其他行程，只去了南昌之星和我们的中国第一大校门拍了照，晚上终于是吃到了我认可的第一美食，成功使用南昌美食留住黛黛的胃哈哈。回酒店的路上听着黛黛的一路高歌，准备第二天一大早五点向毕业旅行第二站<code>云南大理</code>出发！</p><p><code>最后更新时间：2025-06-30 21:17:50</code></p>',12)]))}const u=e(c,[["render",d]]);export{p as __pageData,u as default};
